nta.declaration:
// Bridge / Viking problem: four people cross a bridge at night.
// Crossing times (minutes): A=5, B=10, C=20, D=25. The bridge holds at most two,
// a torch must accompany every crossing, and a pair moves at the slower one's pace.
// Question: can all four reach the safe side within 60 minutes?
const int t[4] = {5, 10, 20, 25};
bool side[4] = {false, false, false, false};   // false = start side, true = safe side
bool torch = false;                             // torch side (starts on the start side)
clock total;                                    // total elapsed time
clock y;                                        // measures the current crossing
int[0,3] ci, cj;                                // who is currently crossing
int[0,25] dur;                                  // duration of the current crossing
